/// Proves the 168 generated conformance blocks cannot pass yet.
///
/// `support::run` is the single seam where the Rust formatting API will be
/// called. Until it exists the seam diverges, and this test asserts exactly
/// that on a real block, so the suite cannot quietly begin reporting coverage.
/// Implementing the API makes this test fail, which is the intended prompt to
/// delete it and un-`#[ignore]` the blocks in the same change.
#[test]
fn the_rust_formatting_api_is_unimplemented_so_all_168_conformance_blocks_are_ignored() {
    let seam = std::panic::catch_unwind(|| support::run(&MODULES[0].1[0]));
    assert!(
        seam.is_err(),
        "support::run returned a value: the port now exists, so this test and the \
#[ignore] attributes on the generated blocks are both stale"
    );
}

/// The generated suite reproduces the recorded oracle inventory exactly.
///
/// This checks the generator, not the port: it says the emitted Rust still
/// carries every block, case and execution the provenance manifest recorded.
#[test]
fn generated_suite_matches_the_recorded_oracle_inventory() {
    let blocks: usize = MODULES.iter().map(|(_, blocks)| blocks.len()).sum();
    let cases: usize = MODULES
        .iter()
        .flat_map(|(_, blocks)| blocks.iter())
        .map(|block| block.cases.len())
        .sum();
    let executions: u32 = MODULES
        .iter()
        .flat_map(|(_, blocks)| blocks.iter())
        .map(|block| block.executions)
        .sum();

    assert_eq!(blocks, support::TOTAL_BLOCKS, "generated test blocks");
    assert_eq!(cases, support::TOTAL_CASES, "generated oracle calls");
    assert_eq!(
        executions,
        support::TOTAL_EXECUTIONS,
        "dynamic assertion executions"
    );
    assert_eq!(
        support::LOCALES.len(),
        support::TOTAL_LOCALES,
        "distinct locales"
    );

    for (file, blocks) in &MODULES {
        for (index, block) in blocks.iter().enumerate() {
            assert_eq!(block.file, *file, "block file");
            assert_eq!(block.test_index as usize, index, "block index in {file}");
            for case in block.cases {
                if let Some(assertion_id) = case.assertion_id {
                    assert!(
                        assertion_id.starts_with(file),
                        "case {} claims assertion {assertion_id} from another file",
                        case.seq
                    );
                }
                if let Some(index) = case.locale {
                    assert!(index < support::LOCALES.len(), "locale index out of range");
                }
            }
        }
    }

    eprintln!(
        "d3-format: {blocks} generated conformance blocks covering {cases} oracle calls \
are compiled but ignored; the Rust formatting API arrives in Phase 2 of \
MIGRATION_TO_RUST.md"
    );
}
